const input = $input.all();
return input.map(item => {
  const body = item.json.body || item.json;
  const user = body.user || body.usuario || body.nombre || 'Donante DonaTrack';
  const badge = body.badge || body.insignia || 'Insignia de Honor';
  const description = body.description || body.descripcion || body.detalle || '¡Gracias por apoyar a DonaTrack y marcar la diferencia!';
  const timestamp = new Date().toISOString();

  const discordPayload = {
    username: "DonaTrack Bot",
    embeds: [
      {
        title: "🏆 ¡Nueva Insignia Otorgada!",
        description: `¡Felicitaciones a **${user}** por obtener un nuevo reconocimiento en **DonaTrack**! 🌟`,
        color: 15844367,
        fields: [
          {
            name: "🎖️ Insignia",
            value: `**${badge}**`,
            inline: true
          },
          {
            name: "👤 Donante",
            value: `**${user}**`,
            inline: true
          },
          {
            name: "📝 Logro",
            value: description,
            inline: false
          }
        ],
        thumbnail: {
          url: "attachment://badge.png"
        },
        footer: {
          text: "DonaTrack • Plataforma de Gestión y Trazabilidad"
        },
        timestamp: timestamp
      }
    ]
  };

  return {
    json: {
      userName: user,
      badgeName: badge,
      description: description,
      discordPayload: discordPayload
    }
  };
});

return [
  { json: { user: 'Juan', donations: 5 } },
  { json: { user: 'Maria', donations: 12 } },
  { json: { user: 'Pedro', donations: 3 } },
  { json: { user: 'Ana', donations: 8 } },
  { json: { user: 'Luis', donations: 1 } },
  { json: { user: 'Juan', donations: 2 } },
  { json: { user: 'Ana', donations: 4 } }
];

const items = $input.all();
const totals = {};

for (const item of items) {
  const user = item.json.user;
  const donations = item.json.donations;
  if (!totals[user]) totals[user] = 0;
  totals[user] += donations;
}

const ranking = Object.keys(totals).map(user => ({
  user: user,
  totalDonations: totals[user]
}));

ranking.sort((a, b) => b.totalDonations - a.totalDonations);

return ranking.map(r => ({ json: r }));

const ranking = $("Calculate Ranking").all().map(item => item.json);
const top3 = ranking.slice(0, 3);
const rest = ranking.slice(3);

const medals = ['🥇 1º Puesto — Líder del Mes', '🥈 2º Puesto', '🥉 3º Puesto'];
const fields = [];

top3.forEach((item, index) => {
  fields.push({
    name: medals[index] || `${index + 1}º Puesto`,
    value: `👤 **${item.user}** • \`${item.totalDonations} donaciones\``,
    inline: index > 0
  });
});

if (rest.length > 0) {
  const restNames = rest.map(r => `**${r.user}** (${r.totalDonations})`).join(', ');
  fields.push({
    name: "👏 Menciones de Honor",
    value: `Gracias a ${restNames} y a cada voluntario por su apoyo incondicional.`,
    inline: false
  });
}

const discordPayload = {
  username: "DonaTrack Bot",
  embeds: [
    {
      title: "📢 ¡Podio & Ranking Mensual de DonaTrack! 🏆",
      description: "Reconocimiento especial a los donantes con mayor impacto de este mes. ¡Gracias por hacer la diferencia! 🌟",
      color: 3447003,
      fields: fields,
      thumbnail: {
        url: "https://api.dicebear.com/9.x/bottts/png?seed=DonaTrackPodium&size=256"
      },
      footer: {
        text: "DonaTrack • Plataforma de Gestión y Trazabilidad"
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{ json: { discordPayload: discordPayload } }];

const input = $input.all();
return input.map(item => {
  const body = item.json.body || item.json;
  const destinatario = body.destinatario || body.user || body.to || 'General';
  const mensaje = body.mensaje || body.message || body.description || 'Notificación sin mensaje';
