  if (medio === 'TELEFONO') medio = 'SMS';

  const timestamp = new Date().toISOString();
  const avatarUrl = 'https://api.dicebear.com/9.x/bottts/png?seed=' + encodeURIComponent(destinatario) + '&size=128';
